/**
 * @param {string} s
 * @return {number}
 */
var minOperations = function(s) {
    let min = 123;
    let minc = 0;
    let max = 97;
    let maxc = 0;
    let sorted = true;

    for (let i = 0; i < s.length; i++) {
        const code = s.charCodeAt(i);

        if (code < min) {
            min = code;
            minc = 1;
        } else if (code === min) {
            minc++;
        }

        if (code > max) {
            max = code;
            maxc = 1;
        } else if (code === max) {
            maxc++;
        }

        if (i > 0 && code < s.charCodeAt(i - 1)) {
            sorted = false;
        }
    }

    const codeFirst = s.charCodeAt(0);
    const codeLast = s.charCodeAt(s.length - 1);

    if (sorted) return 0;
    if (s.length <= 2) return -1;
    if (codeFirst === min || codeLast === max) return 1;
    if (codeFirst === max && maxc === 1 && codeLast === min && minc === 1) return 3;
    return 2;
};
